// Das (1902) reference layer (#61): syllable-onset -> PDF page from
// the team's own bookmarked copy (public-domain text). Reference
// comparanda only, never HGM material.
static std::vector<std::pair<std::string, int>>* g_dasSections =
    nullptr;
static QString g_dasPdfPath;
// Steinert's Das headword index (permission granted by email,
// 2026-08-13) — headword-level pages, his ±page caveat kept in
// the "~p." label; onset sections remain the fallback
static QHash<QString, int>* g_dasHeadwords = nullptr;
static int dasPageFor(const std::string& wylie) {
    if (g_dasHeadwords && !g_dasHeadwords->isEmpty()) {
        QString w = QString::fromStdString(wylie).trimmed();
        while (!w.isEmpty()) {
            auto it = g_dasHeadwords->find(w);
            if (it != g_dasHeadwords->end()) return it.value();
            const int sp = w.lastIndexOf(' ');
            if (sp < 0) break;
            w = w.left(sp);   // longest-prefix headword
        }
    }
    if (!g_dasSections || g_dasSections->empty()) return -1;
    std::string syl = wylie.substr(0, wylie.find(' '));
    int best = -1;
    size_t bestLen = 0;
    for (const auto& [onset, page] : *g_dasSections)
        if (syl.compare(0, onset.size(), onset) == 0 &&
            onset.size() > bestLen) {
            bestLen = onset.size();
            best = page;
        }
    return best;
}
static void showDasPage(QWidget* parent, int page);
// Jäschke 1881 (PD, archive.org scan) — the second page-scan lane,
// letter-level anchors (~page accuracy by design)
static std::vector<std::pair<std::string, int>>* g_jaeSections =
    nullptr;
static QString g_jaePdfPath;
static int jaePageFor(const std::string& wylie) {
    if (!g_jaeSections || g_jaeSections->empty()) return -1;
    std::string syl = wylie.substr(0, wylie.find(' '));
    auto match = [&](const std::string& t) {
        int best = -1;
        size_t bestLen = 0;
        for (const auto& [onset, page] : *g_jaeSections)
            if (t.compare(0, onset.size(), onset) == 0 &&
                onset.size() >= bestLen) {
                bestLen = onset.size();
                best = page;
            }
        return best;
    };
    // strip prefix letters (g d b m ') and superscripts (r l s)
    // down to the root before matching the letter sections —
    // bka/dkar/rkang all live under ka in Jäschke's order
    std::string t = syl;
    for (int pass = 0; pass < 2 && t.size() > 1; ++pass) {
        const char c0 = t[0];
        const bool pre = (c0 == 'g' || c0 == 'd' || c0 == 'b' ||
                          c0 == 'm' || c0 == '\'');
        const bool sup = (c0 == 'r' || c0 == 'l' || c0 == 's');
        if (!pre && !sup) break;
        const char c1 = t[1];
        const bool nextCons =
            std::isalpha((unsigned char)c1) && c1 != 'a' &&
            c1 != 'e' && c1 != 'i' && c1 != 'o' && c1 != 'u';
        // "sh"/"ng"/"dz" etc. are onsets themselves — only strip
        // when the REMAINDER also matches a section
        if (!nextCons) break;
        const std::string rest = t.substr(1);
        if (match(rest) < 0) break;
        // don't split real digraph onsets (sh zh th ph kh ch ng
        // ny ts dz): if the full form already matches a longer
        // onset than the bare first letter, keep it
        if ((c0 == 's' && c1 == 'h') || (c0 == 'd' && c1 == 'z') ||
            (c0 == 'g' && c1 == '.'))
            break;
        t = rest;
    }
    return match(t);
}
static void showJaePage(QWidget* parent, int page);

// normalization MUST mirror tools/build_teaching_index.py terms.txt
static std::string teachingKey(std::string g) {
    std::string t;
    bool inParen = false;
    for (char c : g) {
        if (c == '(') inParen = true;
        else if (c == ')') inParen = false;
        else if (!inParen) t += (char)std::tolower((unsigned char)c);
    }
    std::string u;
    for (char c : t)
        u += (std::isalpha((unsigned char)c) || c == ' ' || c == '-' ||
              c == '\'')
                 ? c
                 : ' ';
    std::istringstream is(u);
    std::string w, out;
    bool first = true;
    while (is >> w) {
        if (first && w == "to") { first = false; continue; }
        first = false;
        out += (out.empty() ? "" : " ") + w;
    }
    return out;
}

