// The published apparatus (GMR-approved, mined from released books):
// 344 footnotes keyed by English lemma + 138 bibliography entries.
// Loaded once; flags terms wherever they appear.
struct ApparatusAnchor {
    QString wylie, asWritten, evidence;
    bool technical = false;
};
struct ApparatusNote {
    QString lemma, text, source;
    int num = 0;
    // Adam, 2026-08-15: "we can see the footnotes output but we don't
    // know what Tibetan phrase/term they are associated with." These
    // are MACHINE-LOCATED CANDIDATES mined from the note's own body
    // (data/extracted/apparatus_anchors.json) and validated against
    // attested spine headwords. A note often names several Tibetan
    // terms and only one is the real anchor, so they are shown as
    // candidates carrying their evidence, never asserted as the term
    // the footnote hangs on.
    std::vector<ApparatusAnchor> anchors;
};
struct ApparatusBib { QString source, section, id, text; };
static const std::vector<ApparatusNote>* g_appNotes = nullptr;
static const std::vector<ApparatusBib>* g_appBib = nullptr;
// the colloquial/prenasal register, for the cards' "also heard" line
static const allcore::ColloquialPron* g_colloquial = nullptr;

// the authority's APPROVED pronunciation rulings — a live layer
// over the canonical engine AND over stored entry phonetics; the
// engine and the dictionary are never modified
static const std::map<std::string, std::string>* g_pronApproved =
    nullptr;

// pronounce a word through the engine, then apply the authority's
// ruling when one exists for exactly this word
// Adam's ruled 'a-chung class (le'ur, le'u — 2026-08-13): a
// syllable-final 'u / 'ur / 'us keeps its apostrophe vowel in the
// DISPLAYED pronunciation ("lay-oo(hr)"). Display layer only — the
// canonical engine and the release data are never edited — and
// PROVISIONAL pending GMR's systematic ruling (TODO: Waiting on
// Adam). Last-syllable scope: inner occurrences await the general
// ruling rather than risking misalignment with engine word grouping.
static std::string restoreAchungU(const std::string& wylie,
                                  std::string pron) {
    if (pron.empty()) return pron;
    static const char* kSufs[] = {"'ur", "'us", "'u"};
    const size_t sp = wylie.find_last_of(' ');
    const std::string last =
        sp == std::string::npos ? wylie : wylie.substr(sp + 1);
    for (const char* sf : kSufs) {
        const std::string suf = sf;
        if (last.size() <= suf.size()) continue;
        if (last.compare(last.size() - suf.size(), suf.size(),
                         suf) != 0)
            continue;
        if (pron.size() >= suf.size() &&
            pron.compare(pron.size() - suf.size(), suf.size(),
                         suf) == 0)
            return pron;   // already carried
        const std::string plain = suf.substr(1);
        if (pron.size() > plain.size() &&
            pron.compare(pron.size() - plain.size(), plain.size(),
                         plain) == 0)
            return pron.substr(0, pron.size() - plain.size()) + suf;
        return pron + suf;
    }
    return pron;
}

static std::string pronWithRulings(const std::string& word_wylie,
                                   const std::string& engine_pron) {
    const std::string base =
        restoreAchungU(word_wylie, engine_pron);
    if (!g_pronApproved) return base;
    auto it = g_pronApproved->find(word_wylie);
    return it == g_pronApproved->end() ? base : it->second;
}

// mark every multi-syllable ruling's run inside a syllable
// sequence (lowercased wylie syllables). Returns true if any run
// was claimed. ruled[i] = index into vals, or -1.
static bool markPhraseRulings(const std::vector<std::string>& syls,
                              std::vector<int>& ruled,
                              std::vector<std::string>& vals) {
    ruled.assign(syls.size(), -1);
    vals.clear();
    if (!g_pronApproved || syls.empty()) return false;
    for (const auto& [rk, rv] : *g_pronApproved) {
        std::vector<std::string> ks;
        std::string cur;
        for (char c : rk) {
            if (c == ' ') {
                if (!cur.empty()) ks.push_back(cur);
                cur.clear();
            } else {
                cur += (char)std::tolower((unsigned char)c);
            }
        }
        if (!cur.empty()) ks.push_back(cur);
        if (ks.size() < 2) continue;
        for (size_t s = 0; s + ks.size() <= syls.size(); ++s) {
            bool hit = true;
            for (size_t j = 0; j < ks.size(); ++j)
                if (syls[s + j] != ks[j] || ruled[s + j] >= 0) {
                    hit = false;
                    break;
                }
            if (hit) {
                vals.push_back(rv);
                for (size_t j = 0; j < ks.size(); ++j)
                    ruled[s + j] = (int)vals.size() - 1;
            }
        }
    }
    return !vals.empty();
}

// card zone label: the gold micro-caps of the left pane, reused as
// the card's grouping device (one idiom everywhere). A hairline
// above separates the zone; 12px of air before it, 4px after.
static QString zoneLabel(const QString& text) {
    return "<div style='border-top:1px solid #E2DACB;margin-top:12px;"
           "padding-top:6px;color:#9A7A33;font-size:10px;"
           "letter-spacing:2px;font-weight:600;margin-bottom:4px'>" +
           text + "</div>";
}

static QString entryHtml(const allcore::Entry& e,
                         const EntryDisplay& d = EntryDisplay{}) {
    QString h;
    h += "<div style='margin-bottom:14px'>";
    h += "<span style='font-size:22px'>" +
         QString::fromStdString(e.tibetan).toHtmlEscaped() + "</span> ";
    // ACIP beside the Tibetan (Adam's ruling 2026-08-12: the
    // input centers' native transliteration, not wylie). Entries
    // without a stored ACIP convert through the round-trip-proven
    // engine; wylie only as a last resort.
    std::string headTrans = e.acip;
    if (headTrans.empty()) headTrans = allcore::ewtsToAcip(e.wylie);
    if (headTrans.empty()) headTrans = e.wylie;
    // identity metadata, not a second headline: the Tibetan leads,
    // the ACIP sits a step smaller (Adam's redundancy ruling)
    h += "<b style='font-size:14px;color:#555'>" +
         QString::fromStdString(headTrans).toHtmlEscaped() + "</b>";
    if (!d.surface.empty())
        h += " <span style='font-size:12px;color:#8A6D1F'>from: " +
             QString::fromStdString(d.surface).toHtmlEscaped() +
             "</span>";
    if (!e.tibetan_source.empty())
        h += " <i style='color:#888'>[generated script]</i>";
    if (d.phonetics && !e.pronunciation.empty()) {
        // the authority's ruling shows wherever pronunciation
        // shows (Adam's finding 2026-08-12: the ruled tsema
        // namdrel wasn't reaching the entry cards)
        std::string cardPron = e.pronunciation;
        bool ruledPron = false;
        if (g_pronApproved) {
            std::string k;
            for (char c : e.wylie)
                k += (char)std::tolower((unsigned char)c);
            auto itr = g_pronApproved->find(k);
            if (itr != g_pronApproved->end()) {
                cardPron = itr->second;
                ruledPron = true;
            } else {
                // a ruled PHRASE inside a longer headword
                // (Adam's finding: tshad ma rnam 'grel gyi tshig
                // le'ur byas pa) — the ruling claims its run and
                // only the remainder re-derives through the
                // battery-proven engine
                std::vector<std::string> syls;
                std::string cur;
                for (char c : k) {
                    if (c == ' ') {
                        if (!cur.empty()) syls.push_back(cur);
                        cur.clear();
                    } else {
                        cur += c;
                    }
                }
                if (!cur.empty()) syls.push_back(cur);
                std::vector<int> ruled;
                std::vector<std::string> vals;
                if (markPhraseRulings(syls, ruled, vals)) {
                    std::string outp;
                    size_t s0 = 0;
                    while (s0 < syls.size()) {
                        if (ruled[s0] >= 0) {
                            const int rid = ruled[s0];
                            while (s0 < syls.size() &&
                                   ruled[s0] == rid)
                                ++s0;
                            outp += (outp.empty() ? "" : " ") +
                                    vals[rid];
                        } else {
                            std::string run;
                            while (s0 < syls.size() &&
                                   ruled[s0] < 0) {
                                run += (run.empty() ? "" : " ") +
                                       syls[s0];
                                ++s0;
                            }
                            const std::string p = restoreAchungU(
                                run, allcore::pronounce(run));
                            outp += (outp.empty() ? "" : " ") +
                                    (p.empty() ? run : p);
                        }
                    }
                    cardPron = outp;
                    ruledPron = true;
                }
            }
        }
        if (!ruledPron)
            cardPron = restoreAchungU(e.wylie, cardPron);
        // the clicked SURFACE form owns the pron line (Adam,
        // 2026-08-13: clicking LE'UR must read le'ur, not the bare
        // headword's le'u — the card already says "from: LE'UR")
        if (!d.surface.empty()) {
            std::string sw =
                QString::fromStdString(
                    allcore::acipToEwts(d.surface))
                    .trimmed()
                    .toLower()
                    .toStdString();
            if (!sw.empty() && sw != e.wylie) {
                bool sruled = false;
                std::string sp;
                if (g_pronApproved) {
                    auto its = g_pronApproved->find(sw);
                    if (its != g_pronApproved->end()) {
                        sp = its->second;
                        sruled = true;
                    }
                }
                if (sp.empty())
                    sp = restoreAchungU(sw,
                                        allcore::pronounce(sw));
                if (!sp.empty() && sp != cardPron) {
                    cardPron = sp;
                    ruledPron = sruled;
                }
            }
        }
        h += "<div style='margin:5px 0 0 0'>pron: " +
             QString::fromStdString(cardPron).toHtmlEscaped();
        if (ruledPron)
            h += " <span style='color:#1E6B4E'>⟪ruled⟫</span>";
        else if (e.pronunciation_card_attested) h += " ⟪card⟫";
        // registered variants: community spellings and the prenasal
        // (kamdir) forms — labeled by class, never replacing the
        // GMR-convention pron above
        if (g_colloquial) {
            QString also;
            for (const auto* v : g_colloquial->byWylie(e.wylie)) {
                if (!also.isEmpty()) also += " · ";
                also += QString::fromStdString(v->colloquial)
                            .toHtmlEscaped() +
                        (v->cls == "prenasal-derived"
                             ? " <span style='color:#999'>(prenasal, "
                               "derived)</span>"
                             : " <span style='color:#999'>(community)"
                               "</span>");
            }
            if (!also.isEmpty())
                h += "<br><small style='color:#666'>also heard: " +
                     also + "</small>";
        }
        h += "</div>";
    }
    if (g_honorifics) {
        auto it = g_honorifics->find(e.wylie);
        if (it != g_honorifics->end()) {
            const auto& [ord, dom, lvl] = it->second;
            h += " <span style='background:#EADFF7;color:#4A2A6B;"
                 "padding:1px 7px;border-radius:8px;font-size:11px'>" +
                 QString(lvl == "high" ? "HIGH honorific"
                         : lvl == "humilific" ? "humilific"
                         : lvl == "double" ? "double honorific"
                                           : "honorific") +
                 " (zhe sa)</span>";
            if (!ord.isEmpty())
                h += " <small style='color:#555'>ordinary: <b>" +
                     ord.toHtmlEscaped() + "</b></small>";
        }
    }
    if (g_idioms) {
        auto it = g_idioms->find(e.wylie);
        if (it != g_idioms->end()) {
            const bool approved = it->second.first == "approved";
            h += QString(" <span style='background:%1;color:%2;"
                         "padding:1px 7px;border-radius:8px;"
                         "font-size:11px' title='%3'>IDIOM%4</span>")
                     .arg(approved ? "#DDEBDC" : "#F2E8CF")
                     .arg(approved ? "#2C5B2E" : "#6E5A1E")
                     .arg(it->second.second.toHtmlEscaped())
                     .arg(approved ? "" : " (proposed)");
        }
    }
    if (d.glosses) {
        for (const auto& g : e.hgm_gloss) {
            QString tier = e.provisional()
                ? "<span style='color:#b00'>PROVISIONAL (auto-aligned)</span>"
                : QString::fromStdString("HGM (" + e.tier + ")");
            h += "<div style='margin:3px 0 0 0'>≡ " +
                 QString::fromStdString(g).toHtmlEscaped() +
                 " &nbsp;<small>[" + tier + "]</small></div>";
        }
        if (e.hgm_gloss.empty()) {
            h += "<div style='margin:3px 0 0 0'><i>(no HGM "
                 "equivalent — " +
                 QString::fromStdString(e.status).toHtmlEscaped() +
                 ")</i></div>";
            // the ALL Working Glossary (Adam, 2026-08-12): an
            // AI-drafted gloss may exist for HGM-less terms —
            // synthesized ONLY from reference comparanda (never
            // Geshe Michael's English), unmistakably bannered,
            // and shown ONLY where HGM is silent
            if (g_aiGlossary) {
                auto it = g_aiGlossary->find(e.wylie);
                if (it != g_aiGlossary->end()) {
                    const AiGloss& a = it->second;
                    QString b =
                        "<div style='background:#EDE9F5;"
                        "border-left:3px solid #7A5EA8;"
                        "padding:4px 9px;margin:4px 0;"
                        "border-radius:4px'>"
                        "<small style='color:#4A2A6B;"
                        "letter-spacing:1px'>ALL WORKING GLOSSARY "
                        "— AI-DRAFTED, PROVISIONAL · not Geshe "
                        "Michael's English</small><br>";
                    if (!a.pos.isEmpty())
                        b += "<span style='color:#A33;'>&lt;" +
                             a.pos.toHtmlEscaped() +
                             "&gt;</span> <small style='color:#777'>"
                             "(" + a.posSrc.toHtmlEscaped() +
                             ")</small> ";
                    if (!a.senses.isEmpty()) {
                        static const char* rn[] = {"I", "II", "III"};
                        for (int si = 0; si < a.senses.size() &&
                                          si < 3; ++si) {
                            b += QString("<br><b>%1.</b> ")
                                     .arg(rn[si]) +
                                 a.senses[si].first.toHtmlEscaped();
                            if (!a.senses[si].second.isEmpty())
                                b += " — <span style='color:#333'>" +
                                     a.senses[si]
                                         .second.toHtmlEscaped() +
                                     "</span>";
                        }
                    } else {
                        b += "<br>≡ " + a.gloss.toHtmlEscaped();
                    }
                    if (!a.sanskrit.isEmpty())
                        b += "<br><small style='color:#666'>"
                             "sanskrit (LC): " +
                             a.sanskrit.toHtmlEscaped() + "</small>";
                    if (!a.seeAlso.isEmpty()) {
                        b += "<br><small>see also: ";
                        for (const QString& w : a.seeAlso)
                            b += "<a href='term:" + anchorEnc(w) +
                                 "'>" + w.toHtmlEscaped() +
                                 "</a> · ";
                        b.chop(3);
                        b += "</small>";
                    }
                    b += "<br><small style='color:#777'>[" +
                         a.model.toHtmlEscaped() + " · " +
                         a.date.toHtmlEscaped() + " · from " +
                         a.grounded.toHtmlEscaped() +
                         " · q.v. links open the Lookup]</small>";
                    b += "<br><small><a href='proposeai:" +
                         anchorEnc(QString::fromStdString(
                             e.wylie)) +
                         "'>review & promote this draft to the "
                         "authority…</a></small>"
                         "</div>";
                    h += b;
                }
            }
        }
    }
    if (d.notes && g_appNotes && !e.hgm_gloss.empty()) {
        int shownNotes = 0;
        for (const auto& note : *g_appNotes) {
            bool hit = false;
            for (const auto& g : e.hgm_gloss)
                if (!note.lemma.isEmpty() &&
                    QString::fromStdString(g).contains(note.lemma,
                                                       Qt::CaseInsensitive))
                    hit = true;
            if (hit) {
                h += "<div style='background:#F3EDDF;padding:3px 7px;"
                     "border-radius:4px;margin:7px 0 2px 0;"
                     "font-size:11px'>"
                     "\U0001F4CE <b>published footnote " +
                     QString::number(note.num) + "</b> (" +
                     note.lemma.toHtmlEscaped() + ") \u2014 <i>" +
                     note.source.toHtmlEscaped() + "</i><br>" +
                     note.text.left(280).toHtmlEscaped() +
                     "</div>";
                if (++shownNotes >= 2) break;
            }
        }
    }
    if (d.das && g_dasSections && !e.wylie.empty()) {
        const int pg = dasPageFor(e.wylie);
        if (pg > 0)
            h += QString("<div style='margin-top:7px'><small>"
                         "<a href='das:%1' style='color:#666'>"
                         "Das 1902 dictionary \u00b7 open the "
                         "page scan (~p.%1, reference)</a>"
                         "</small></div>")
                     .arg(pg);
    }
    if (d.das && g_jaeSections && !e.wylie.empty()) {
        const int pg = jaePageFor(e.wylie);
        if (pg > 0)
            h += QString("<div style='margin-top:2px'><small>"
                         "<a href='jae:%1' style='color:#666'>"
                         "J\u00e4schke 1881 dictionary \u00b7 "
                         "open the page scan (\u00b1page, "
                         "reference)</a></small></div>")
                     .arg(pg);
    }
    if (d.sanskrit && !e.sanskrit_reference.empty())
        h += "<div style='margin-top:4px'><small style='color:#6E675D'>"
             "sanskrit (reference): " +
             QString::fromStdString(e.sanskrit_reference).left(160).toHtmlEscaped() +
             "</small></div>";
    if (d.hopkins && !e.hopkins_reference.empty())
        h += "<div style='margin-top:2px'><small style='color:#6E675D'>"
             "Hopkins (reference only): " +
             QString::fromStdString(e.hopkins_reference).left(200).toHtmlEscaped() +
             "</small></div>";
    if (d.g84000 && g_84000) {
        auto it = g_84000->find(e.wylie);
        if (it != g_84000->end()) {
            const G84000& g = it->second;
            QString b = "<div style='border-left:2px solid #B8AD9C;"
                        "padding:2px 0 2px 8px;margin:6px 0'>"
                        "<small style="
                        "'color:#8A7E6E;letter-spacing:1px'>"
                        "84000 GLOSSARY · CC BY 4.0 · reference "
                        "only</small>";
            for (const QString& x : g.glosses)
                b += "<br>≡ " + x.toHtmlEscaped();
            for (QString x : g.defs) {
                // keep the entity link to 84000, clickable
                static const QRegularExpression lk(
                    "\(Original glossary entry: (https[^)\s]+)\)");
                const auto m = lk.match(x);
                QString url;
                if (m.hasMatch()) {
                    url = m.captured(1);
                    x.remove(m.captured(0));
                }
                b += "<br><small>" +
                     x.trimmed().left(400).toHtmlEscaped() +
                     (url.isEmpty()
                          ? QString()
                          : " <a href='" + url + "'>[84000]</a>") +
                     "</small>";
            }
            for (const QString& x : g.skts)
                b += "<br><small style='color:#6E675D'>sanskrit: " +
                     x.left(160).toHtmlEscaped() + "</small>";
            b += "</div>";
            h += b;
        }
    }
    if (g_teachingTib && !e.wylie.empty()) {
        std::vector<const TeachingMoment*> ms;
        std::set<QString> seen;
        {
            auto it = g_teachingTib->find(e.wylie);
            if (it != g_teachingTib->end())
                for (const auto& m : it->second)
                    if (!seen.count(m.url) && ms.size() < 3) {
                        seen.insert(m.url);
                        ms.push_back(&m);
                    }
        }
        if (!ms.empty()) {
            h += zoneLabel("IN THE RECORDED TEACHINGS") +
                 "<div style='font-size:12px'><i "
                 "style='color:#9C948A'>moments where he says the "
                 "TIBETAN phrase itself (phonetic match on his "
                 "own convention \u2014 candidates; homophones "
                 "share moments; the recording is the "
                 "authority)</i><br>";
            for (const auto* m : ms) h += teachingRow(*m);
            h += "</div>";
        }
    }
    // Second tier, restored 2026-08-15 (Adam: "not being linked any
    // longer"). The Tibetan-spoken tier above is his ruling and stays
    // FIRST; this one matches on the entry's ENGLISH equivalent, which
    // is what gave the card broad coverage before 2026-08-14 — the
    // spoken-Tibetan index reaches 6,195 headwords, the English index
    // 8,518 terms, so Tibetan-only left ~94% of lookups with nothing.
    // Labeled distinctly so the two kinds of match are never confused.
    if (g_teaching && !e.hgm_gloss.empty()) {
        std::vector<const TeachingMoment*> ms;
        std::set<QString> seen;
        for (const auto& g : e.hgm_gloss) {
            auto it = g_teaching->find(teachingKey(g));
            if (it == g_teaching->end()) continue;
            for (const auto& m : it->second)
                if (!seen.count(m.url) && ms.size() < 3) {
                    seen.insert(m.url);
                    ms.push_back(&m);
                }
        }
        if (!ms.empty()) {
            h += "<div style='margin-top:4px;font-size:12px'>"
                 "<span style='color:#7C2D26;font-weight:600'>He "
                 "teaches this idea</span> <i style='color:#888'>"
                 "(located by the ENGLISH equivalent in the class "
                 "captions \u2014 the recording is the "
                 "authority)</i><br>";
            for (const auto* m : ms) h += teachingRow(*m);
            h += "</div>";
        }
    }
    h += "</div>";
    return h;
}

// Link-out tier (survey): external sites searched for a term — links only,
// no ingestion, so restrictive licenses (BY-NC-ND etc.) are never touched.
// Every URL format verified live 2026-08-07; Adarsha RESTORED
// 2026-08-14: the rebuilt site (adarshah.org) reads search.html?text=
// (Tibetan unicode) and auto-runs the query — verified live in the
// browser (results rendered). The link passes unicode from our proven
// converter; a form it refuses simply gets no Adarsha link.
static QString linkOutHtml(const std::string& wylie) {
    const QString q = QString::fromUtf8(
        QUrl::toPercentEncoding(QString::fromStdString(wylie)));
    QString h =
        "<div style='color:#777;font-size:11px;margin-top:6px'>search "
        "elsewhere <i>(external sites, links only)</i>: ";
    h += "<a href='https://84000.co/search?query=" + q + "'>84000</a> · ";
    h += "<a href='https://library.bdrc.io/search?q=%22" + q +
         "%22~1&lg=bo-x-ewts&t=Etext'>BDRC etexts</a> · ";
    h += "<a href='https://www2.hf.uio.no/polyglotta/index.php?page=search&q=" +
         q + "'>Bibliotheca Polyglotta</a> · ";
    h += "<a href='https://www.lotsawahouse.org/search?q=" + q +
         "'>Lotsawa House</a> · ";
    // Adarsha (Dharma Treasure): Kangyur/Tengyur/Sungbum full-text —
    // wants Tibetan unicode, not wylie
    {
        auto [uni, uok] = allcore::wylieToUnicode(wylie);
        if (uok)
            h += "<a href='https://online.adarshah.org/search.html?"
                 "text=" +
                 QString::fromUtf8(QUrl::toPercentEncoding(
                     QString::fromStdString(uni))) +
                 "'>Adarsha</a> · ";
    }
    // THL Places gazetteer (~64k Tibetan places; the ?searchTerm
    // pattern is the app's own search URL — verified live
    // 2026-08-13, Sera Monastery → features/433)
    h += "<a href='https://places.kmaps.virginia.edu/?searchTerm=" +
         q + "'>THL Places</a></div>";
    return h;
}

static QString mvpHtml(const std::vector<const allcore::MvpEntry*>& hits) {
    if (hits.empty()) return {};
    QString h = "<hr><div style='color:#4A3B7A'><b>Mahāvyutpatti</b> "
                "<small>(DILA TEI, CC BY-SA 3.0 — the classical 9th-century "
                "Skt⇄Tib glossary; reference only)</small></div>";
    for (const auto* e : hits) {
        QString tib;
        for (const auto& t : e->tibetan)
            tib += (tib.isEmpty() ? "" : " · ") +
                   QString::fromStdString(t).toHtmlEscaped();
        QString wy;
        for (const auto& w : e->wylie)
            wy += (wy.isEmpty() ? "" : " · ") +
                  QString::fromStdString(w).toHtmlEscaped();
        h += QString("<div style='margin:5px 0'><b>MVP %1</b> · %2 "
                     "<span style='font-size:18px'>%3</span> · %4</div>")
                 .arg(e->key)
                 .arg(QString::fromStdString(e->iast).toHtmlEscaped(),
                      tib, wy);
    }
    return h;
}

static HonorificMap loadHonorifics(const QString& path) {
    HonorificMap m;
    QFile f(path);
    if (!f.open(QIODevice::ReadOnly | QIODevice::Text)) return m;
    while (!f.atEnd()) {
        const QString line = QString::fromUtf8(f.readLine()).trimmed();
        if (line.isEmpty() || line.startsWith('#')) continue;
        const QStringList c = line.split('\t');
        if (c.size() < 4) continue;
        m[c[0].toStdString()] = {c[1], c[2], c[3]};
    }
    return m;
}

// ---- data-release updater helpers (loose-ends item 8) ----
// The spine the app opens is chosen by build/spine_current.txt when
// the release importer has written one; otherwise the pinned
// default. The pointer holds a bare filename — anything with a path
// separator is refused (never trust a file to escape build/).
static QString resolveSpinePath(const QString& root) {
    const QString def = root + "/build/hgm_spine_v27_2.db";
    QFile ptr(root + "/build/spine_current.txt");
    if (ptr.open(QIODevice::ReadOnly | QIODevice::Text)) {
        const QString name =
            QString::fromUtf8(ptr.readLine()).trimmed();
        if (!name.isEmpty() && !name.contains('/') &&
            !name.contains("..")) {
            const QString p = root + "/build/" + name;
            if (QFileInfo::exists(p)) return p;
        }
    }
    return def;
}

// What a release folder offers: the newest version of each expected
// file (master required; corpus and reverse index optional — the
// builder falls back to the pinned ones when absent).
struct ReleasePkg {
    QString master, corpus, reverse;  // absolute paths ("" = absent)
    QString version;                  // e.g. "v28_0" (from the master)
};
static ReleasePkg discoverReleasePackage(const QString& dir) {
    ReleasePkg pkg;
    auto newest = [&](const QString& prefix, const QString& suffix,
                      QString* verOut) {
        QString best;
        long long bestV = -1;
        QDir d(dir);
        for (const QFileInfo& fi :
             d.entryInfoList(QDir::Files | QDir::Readable)) {
            const QString n = fi.fileName();
            if (!n.startsWith(prefix) || !n.endsWith(suffix)) continue;
            static const QRegularExpression rx(
                "_v(\\d+)(?:_(\\d+))?\\.");
            const auto m = rx.match(n);
            if (!m.hasMatch()) continue;
            const long long v = m.captured(1).toLongLong() * 1000 +
                                m.captured(2).toLongLong();
            if (v > bestV) {
                bestV = v;
                best = fi.absoluteFilePath();
                if (verOut)
                    *verOut = "v" + m.captured(1) + "_" +
                              (m.captured(2).isEmpty()
                                   ? "0"
                                   : m.captured(2));
            }
        }
        return best;
    };
    pkg.master =
        newest("hgm_dictionary_", ".json.gz", &pkg.version);
    pkg.corpus = newest("full_parallel_corpus_", ".json.gz", nullptr);
    pkg.reverse = newest("hgm_reverse_index_", ".json", nullptr);
    return pkg;
}

// The Lookup pane's whole stacked search, extracted for the
// selftest: HGM binding layer first, reference layers labeled,
// honorific badges, colloquial variants, link-outs.
static QString lookupResultsHtml(allcore::Spine& spine,
                                 allcore::RefDict* ref,
                                 allcore::Mvp* mvp,
                                 allcore::WhitneyRoots* whitney,
                                 allcore::ColloquialPron* colloq,
                                 const std::string& raw) {
    auto entries = spine.lookup(raw);
    if (entries.empty()) entries = spine.headwordSearch('"' + raw + '"', 10);
    QString h;
    // affix-stripping fallback (lucene-bo rules): po'i finds po
    if (entries.empty()) {
        bool upper = false;
        for (char c : raw) upper |= (c >= 'A' && c <= 'Z');
        const std::string wy = upper ? allcore::acipToEwts(raw) : raw;
        const std::string base =
            allcore::stripAffixedParticlesWylie(wy);
        if (base != wy) {
            entries = spine.lookup(base);
            if (!entries.empty())
                h += QString("<div style='color:#1E6B4E;font-size:"
                             "12px'>no entry for \u201c%1\u201d — "
                             "showing <b>%2</b> (affixed particle "
                             "stripped)</div>")
                         .arg(QString::fromStdString(wy)
                                  .toHtmlEscaped(),
                              QString::fromStdString(base)
                                  .toHtmlEscaped());
        }
        // the rest of the lucene-bo analyzer chain, aligned with
        // the index fold (searchFoldWylie): standalone ba/bo →
        // pa/po, then non-present verb forms → their unique
        // present stem (CC0 verbs bank; ambiguous forms were
        // never folded). Each step labeled, never silent.
        const std::string paba = allcore::paBaFoldWylie(base);
        if (entries.empty() && paba != base) {
            entries = spine.lookup(paba);
            if (!entries.empty())
                h += QString("<div style='color:#1E6B4E;font-size:"
                             "12px'>no entry for \u201c%1\u201d — "
                             "showing <b>%2</b> (standalone ba/bo "
                             "folds to pa/po)</div>")
                         .arg(QString::fromStdString(wy)
                                  .toHtmlEscaped(),
                              QString::fromStdString(paba)
                                  .toHtmlEscaped());
        }
        if (entries.empty()) {
            if (const auto* lf = allcore::globalLemmaFold()) {
                if (const std::string* stem = lf->fold(paba)) {
                    entries = spine.lookup(*stem);
                    if (!entries.empty())
                        h += QString(
                                 "<div style='color:#1E6B4E;"
                                 "font-size:12px'>\u201c%1\u201d "
                                 "is a verb form — showing the "
                                 "present stem <b>%2</b> (CC0 "
                                 "verb bank)</div>")
                                 .arg(QString::fromStdString(wy)
                                          .toHtmlEscaped(),
                                      QString::fromStdString(*stem)
                                          .toHtmlEscaped());
                }
            }
        }
    }
    // pronunciation fallback (GMR convention): 'jangchub' finds
    // byang chub — deterministic fold, labeled
    bool viaPron = false;
    if (entries.empty()) {
        entries = spine.lookupByPronunciation(raw, 8);
        viaPron = !entries.empty();
    }
    if (viaPron)
        h += "<div style='color:#1E6B4E;font-size:12px'>matched by "
             "<b>pronunciation</b> (GMR convention) — no exact "
             "headword for \u201c" +
             QString::fromStdString(raw).toHtmlEscaped() +
             "\u201d</div>";
    // the authority's ruled pronunciations widen search too:
    // typing the RULED form (tsema namdrel) finds the entry even
    // though the release index only knows the engine's baseline
    if (entries.empty() && g_pronApproved) {
        auto fold = [](const std::string& s) {
            std::string o;
            for (char c : s)
                if (std::isalpha((unsigned char)c))
                    o += (char)std::tolower((unsigned char)c);
            return o;
        };
        const std::string q = fold(raw);
        if (q.size() >= 3) {
            for (const auto& [rw, rp] : *g_pronApproved) {
                const std::string fp = fold(rp);
                if (fp == q ||
                    (q.size() >= 5 && fp.rfind(q, 0) == 0)) {
                    for (auto& e2 : spine.lookup(rw)) {
                        bool dup = false;
                        for (auto& x : entries)
                            dup |= x.id == e2.id;
                        if (!dup) entries.push_back(e2);
                    }
                }
            }
            if (!entries.empty())
                h += "<div style='color:#1E6B4E;font-size:12px'>"
                     "matched by the authority's <b>ruled "
                     "pronunciation</b> \u27EA""ruled\u27EB"
                     "</div>";
        }
    }
    // colloquial register fallback: community spellings (gonpa,
    // tulku\u2026) and the HGM prenasal forms (kamdir) \u2014 the register
    // only WIDENS lookup, GMR stays canonical
    if (entries.empty() && colloq) {
        for (const auto* ce : colloq->byColloquial(raw)) {
            auto hits = spine.lookup(ce->wylie);
            bool any = false;
            for (auto& e : hits) {
                bool dup = false;
                for (auto& x : entries) dup |= x.id == e.id;
                if (!dup) {
                    entries.push_back(std::move(e));
                    any = true;
                }
            }
            if (any)
                h += QString("<div style='color:#1E6B4E;font-size:"
                             "12px'>matched by <b>colloquial "
                             "pronunciation</b> (%1: %2 = %3%4)"
                             "</div>")
                         .arg(ce->cls == "prenasal-derived"
                                  ? "prenasal rule, derived"
                                  : "community usage register")
                         .arg(QString::fromStdString(ce->colloquial)
                                  .toHtmlEscaped())
                         .arg(QString::fromStdString(ce->wylie)
                                  .toHtmlEscaped())
                         .arg(ce->gmrPron.empty()
                                  ? QString()
                                  : "; GMR convention: " +
                                        QString::fromStdString(
                                            ce->gmrPron)
                                            .toHtmlEscaped());
        }
    }
    if (entries.empty()) h = "<i>no HGM match</i>";
    // (honorific badges render inside entryHtml, every pane alike)
    EntryDisplay ld;
    ld.das = QSettings("ALL", "TranslationTool")
                 .value("lookup/showRefs", true)
                 .toBool();
    for (const auto& e : entries) h += entryHtml(e, ld);

    if (ref && QSettings("ALL", "TranslationTool")
                   .value("lookup/showRefs", true)
                   .toBool()) {
        // resolve to wylie for the reference layers (they key on wylie)
        std::string wylie = raw;
        if (!entries.empty()) wylie = entries.front().wylie;
        else {
            // uppercase input = ACIP
            bool upper = false;
            for (char c : raw) upper |= (c >= 'A' && c <= 'Z');
            if (upper) wylie = allcore::acipToEwts(raw);
        }
        auto refs = ref->lookup(wylie);
        if (!refs.empty()) {
            h += zoneLabel("REFERENCE · LOCAL ONLY") +
                 "<div><small style='color:#9C948A'>unlicensed "
                 "compilations — local lookup only, never for "
                 "release data</small></div>";
            for (const auto& r : refs) {
                h += "<div style='margin:5px 0;font-size:12px;"
                     "color:#6E675D'><span style='background:"
                     "#F0E9DC;color:#6B5E4A;padding:1px 7px;border-radius:8px;"
                     "font-size:11px'>" +
                     QString::fromStdString(r.layer).toHtmlEscaped() +
                     "</span> " +
                     QString::fromStdString(r.definition)
                         .left(500)
                         .toHtmlEscaped() +
                     "</div>";
            }
        }
    }
    // user-supplied StarDict dictionaries (P5): exact lookups in
    // three key spaces (as typed, wylie, Tibetan unicode)
    if (!g_stardictsLoaded) loadStardicts();
    if (!g_stardicts.empty()) {
        std::string wylie = raw;
        {
            bool upper = false;
            for (char c : raw) upper |= (c >= 'A' && c <= 'Z');
            if (upper) wylie = allcore::acipToEwts(raw);
        }
        auto [uni, uok] = allcore::wylieToUnicode(wylie);
        bool any = false;
        QString block;
        for (const auto& d : g_stardicts) {
            std::vector<std::string> defs = d->lookup(raw);
            if (defs.empty()) defs = d->lookup(wylie);
            if (defs.empty() && uok) defs = d->lookup(uni);
            if (defs.empty() && uok)
                defs = d->lookup(uni + "\u0F0B");
            if (defs.empty()) continue;
            any = true;
            block += "<div style='margin:5px 0;font-size:12px;"
                     "color:#6E675D'><span style='background:"
                     "#F0E9DC;color:#6B5E4A;padding:1px 7px;"
                     "border-radius:8px;font-size:11px'>" +
                     QString::fromStdString(d->bookname())
                         .toHtmlEscaped() +
                     "</span> ";
            for (size_t k = 0; k < defs.size() && k < 3; ++k)
                block += QString::fromStdString(defs[k])
                             .left(600)
                             .toHtmlEscaped()
                             .replace("\n", "<br>") +
                         (k + 1 < defs.size() ? "<br>" : "");
            block += "</div>";
        }
        if (any) {
            h += zoneLabel("LOCAL DICTIONARIES \u00b7 "
                           "USER-SUPPLIED") +
                 "<div><small style='color:#9C948A'>StarDict "
                 "files you installed \u2014 their licenses are "
                 "their own; local display only</small></div>" +
                 block;
        }
    }
    // Mahāvyutpatti: classical Skt⇄Tib reference (exact wylie match)
    if (mvp) {
        std::string wylie = raw;
        if (!entries.empty()) wylie = entries.front().wylie;
        else {
            bool upper = false;
            for (char c : raw) upper |= (c >= 'A' && c <= 'Z');
            if (upper) wylie = allcore::acipToEwts(raw);
        }
        h += mvpHtml(mvp->byWylie(wylie));
    }
    // Whitney reference layer (Roots 1885 + Grammar 1879 citations;
    // public domain, digitization Apache-2.0 — data/whitney/):
    // Latin queries only — try as an IAST root, else as an English
    // meaning word. Reference comparanda, never HGM equivalents.
    {
        bool hasAlpha = false;
        for (unsigned char c : raw)
            hasAlpha |= std::isalpha(c) != 0;
        bool hasTibetan = false;   // U+0F00–U+0FFF = E0 BC/BD/BE/BF …
        for (size_t i = 0; i + 2 < raw.size(); ++i)
            if ((unsigned char)raw[i] == 0xE0 &&
                ((unsigned char)raw[i + 1] & 0xFC) == 0xBC)
                hasTibetan = true;
        if (whitney && hasAlpha && !hasTibetan) {
            auto roots = whitney->byRoot(raw);
            QString matchKind = "root";
            if (roots.empty()) {   // past participle: gata -> gam
                roots = whitney->byPpp(raw);
                if (!roots.empty()) matchKind = "past participle";
            }
            if (roots.empty() && raw.find(' ') == std::string::npos) {
                roots = whitney->byMeaning(raw, 8);
                if (!roots.empty()) matchKind = "English meaning";
            }
            if (!roots.empty()) {
                h += "<hr><div style='color:#4A3A7A'><b>Whitney — "
                     "Roots, Verb-Forms and Primary Derivatives "
                     "(1885)</b> <small>(public-domain reference; "
                     "matched by " + matchKind + ")</small></div>";
                for (const auto* r : roots) {
                    h += "<div style='margin:6px 0'><b>";
                    if (!r->homonym.empty())
                        h += QString::fromStdString(r->homonym) + " ";
                    h += "√" +
                         QString::fromStdString(r->root)
                             .toHtmlEscaped() +
                         "</b> “" +
                         QString::fromStdString(r->meaning)
                             .toHtmlEscaped() +
                         "”";
                    if (!r->classes.empty())
                        h += " · class " +
                             QString::fromStdString(r->classes)
                                 .replace("|", "·")
                                 .toHtmlEscaped();
                    if (!r->classUncertain.empty())
                        h += " <small style='color:#777'>(also? " +
                             QString::fromStdString(r->classUncertain)
                                 .replace("|", "·")
                                 .toHtmlEscaped() +
                             ")</small>";
                    if (!r->ppp.empty())
                        h += " · ppp <b>" +
                             QString::fromStdString(r->ppp)
                                 .toHtmlEscaped() +
                             "</b>";
                    if (!r->dcsClasses.empty() &&
                        r->dcsClasses != "—")
                        h += " · <small style='color:#777'>corpus: " +
                             QString::fromStdString(r->dcsClasses)
                                 .toHtmlEscaped() +
                             "</small>";
                    if (!r->senses.empty())
                        h += "<br><small style='color:#555'>MW: " +
                             QString::fromStdString(r->senses)
                                 .left(140)
                                 .toHtmlEscaped() +
                             "</small>";
                    // DCS corpus attestation (the last-four
                    // fields, banked 2026-08-14): count + rank as
                    // plain facts; Warnemyr conjugation tables
                    // link-out (path verified live 2026-08-14);
                    // Apte id shown labeled — no unverified URL
                    if (!r->dcsFreq.empty() && r->dcsFreq != "0")
                        h += " · <small style='color:#777'>DCS " +
                             QString::fromStdString(r->dcsFreq)
                                 .toHtmlEscaped() +
                             "×" +
                             (r->dcsRank.empty()
                                  ? QString()
                                  : ", rank " +
                                        QString::fromStdString(
                                            r->dcsRank)
                                            .toHtmlEscaped()) +
                             "</small>";
                    if (!r->warnemyr.empty())
                        h += " <small><a href='http://www.warnemyr"
                             ".com/skrgram/grammar/roots/" +
                             QString::fromStdString(r->warnemyr)
                                 .toHtmlEscaped() +
                             "'>conjugation tables →</a></small>";
                    if (!r->apteId.empty())
                        h += " <small style='color:#999'>· Apte id " +
                             QString::fromStdString(r->apteId)
                                 .toHtmlEscaped() +
                             "</small>";
                    // link-out: Cologne MW display, SLP1-keyed
                    // (URL format verified live 2026-08-08)
                    if (!r->mwId.empty() && !r->slp1.empty())
                        h += " <small><a href='https://"
                             "sanskrit-lexicon.uni-koeln.de/scans/"
                             "MWScan/2020/web/webtc/getword.php?"
                             "key=" +
                             QString::fromStdString(r->slp1)
                                 .toHtmlEscaped() +
                             "&filter=roman'>MW entry →</a></small>";
                    if (!r->grammarSecs.empty() &&
                        r->grammarSecs != "—")
                        h += "<br><small style='color:#555'>Sanskrit "
                             "Grammar (1879) " +
                             QString::fromStdString(r->grammarSecs)
                                 .left(160)
                                 .toHtmlEscaped() +
                             " <span style='color:#777'>(✦ "
                             "specific · ⚠ exception)"
                             "</span></small>";
                    if (!r->sectionRefs.empty()) {
                        // topical ranges: perfect:781-823|… → a
                        // compact by-topic index into the Grammar
                        QString topics;
                        const QStringList parts =
                            QString::fromStdString(r->sectionRefs)
                                .split('|');
                        int shown = 0;
                        for (const QString& p2 : parts) {
                            if (shown++ >= 6) {
                                topics += QString("· +%1 more ")
                                              .arg(parts.size() - 6);
                                break;
                            }
                            QString t2 = p2;
                            t2.replace(':', " §§");
                            t2.replace('_', ' ');
                            topics += t2.toHtmlEscaped() + " · ";
                        }
                        if (!topics.isEmpty())
                            h += "<br><small style='color:#777'>"
                                 "Grammar by topic: " +
                                 topics + "</small>";
                    }
                    h += "</div>";
                }
                h += "<div style='font-size:11px;color:#777'>read "
                     "the Grammar itself: <a href='https://archive."
                     "org/details/sanskritgrammari00whituoft'>"
                     "archive.org scan (public domain)</a></div>";
            }
        }
    }
    // link-out tier: external searches for the resolved term
    {
        std::string wylie = raw;
        if (!entries.empty()) wylie = entries.front().wylie;
        else {
            bool upper = false;
            for (char c : raw) upper |= (c >= 'A' && c <= 'Z');
            if (upper) wylie = allcore::acipToEwts(raw);
        }
        h += linkOutHtml(wylie);
    }
    // English reverse lookup (release reverse index, binding layer)
    {
        std::string eng = raw;
        for (auto& c : eng) c = (char)std::tolower((unsigned char)c);
        auto rev = spine.reverseIndex(eng);
        if (!rev.empty()) {
            h += "<hr><div><b>English \u2192 Tibetan</b> <small>(HGM reverse "
                 "index)</small></div>";
            for (const auto& r : rev) {
                QString tier = r.tier == "auto-aligned"
                    ? "<span style='color:#b00'>PROVISIONAL</span>"
                    : QString::fromStdString("HGM (" + r.tier + ")");
                h += "<div style='margin:5px 0'><b>" +
                     QString::fromStdString(r.wylie).toHtmlEscaped() + "</b> \u00b7 " +
                     QString::fromStdString(r.pronunciation).toHtmlEscaped() +
                     " &nbsp;<small>[" + tier + "]</small></div>";
            }
        }
    }
    // People layer: a query that IS a catalog author's name gets the
    // PERSON card (BDRC / Treasury of Lives), same authority as the
    // Library info panel
    if (g_personCardByName)
        h += g_personCardByName(QString::fromStdString(raw));
    // the proposal channel, reachable while looking things up
    h += QString("<div style='margin-top:8px;font-size:12px'>"
                 "<a href='propose:%1'>propose to the authority\u2026"
                 "</a></div>")
             .arg(anchorEnc(QString::fromStdString(raw)));

    return h;
}

// propose a term to the authority from anywhere a card shows it —
// kind picker + proposed value, filed through the shared channel
static void proposeTermDialog(QWidget* parent, const QString& wylie,
                              const QString& evidence) {
    const QStringList kinds = {
        "Honorific term (\u2194 ordinary)", "HIGH honorific marking",
        "Pronunciation exception", "Abbreviation / contraction candidate",
        "Rendering for this word (\u2192 dictionary)",
        "Idiom / fixed expression", "Note about this term"};
    bool ok = false;
    const QString choice = QInputDialog::getItem(
        parent, "Propose to the authority",
        "What are you proposing for \u201c" + wylie + "\u201d?", kinds, 0,
        false, &ok);
    if (!ok) return;
    allcore::ProposalKind kind = allcore::ProposalKind::WordRendering;
    if (choice.startsWith("Honorific")) kind = allcore::ProposalKind::Honorific;
    else if (choice.startsWith("HIGH"))
        kind = allcore::ProposalKind::HighHonorific;
    else if (choice.startsWith("Pronunciation"))
        kind = allcore::ProposalKind::Pronunciation;
    else if (choice.startsWith("Abbreviation"))
        kind = allcore::ProposalKind::Abbreviation;
    else if (choice.startsWith("Idiom"))
        kind = allcore::ProposalKind::Idiom;
    else if (choice.startsWith("Note")) kind = allcore::ProposalKind::Note;
    QString value;
    if (kind != allcore::ProposalKind::Note) {
        value = QInputDialog::getText(
            parent, "Proposed value",
            kind == allcore::ProposalKind::Pronunciation
                ? "Proposed pronunciation:"
                : (kind == allcore::ProposalKind::Honorific
                       ? "Ordinary counterpart (or leave blank):"
                       : "Proposed English / expansion:"),
            QLineEdit::Normal, "", &ok);
        if (!ok) return;
    }
    QString field;
    if (kind == allcore::ProposalKind::Honorific ||
        kind == allcore::ProposalKind::HighHonorific ||
        kind == allcore::ProposalKind::Humilific ||
        kind == allcore::ProposalKind::DoubleHonorific) {
        field = value;
        value.clear();
    }
    loadIdentity();
    fileProposal(parent, kind, wylie, value, field, evidence);
}

// the Working Glossary's promotion lane (closes task #17's app
// side): an AI-drafted entry may be PROMOTED into a real proposal
// for the authority — the human reviews and may edit the gloss,
// then it files as an ordinary word-rendering proposal whose
// evidence records the draft's full provenance. The draft itself
// never touches the dictionary; only the approved proposal can.
static void promoteAiDraftDialog(QWidget* parent,
                                 const QString& wylie) {
    if (!g_aiGlossary) return;
    auto it = g_aiGlossary->find(wylie.toStdString());
    if (it == g_aiGlossary->end()) return;
    const AiGloss& a = it->second;
    bool ok = false;
    const QString value = QInputDialog::getText(
        parent, "Promote AI draft to the authority",
        "Review the draft rendering for “" + wylie +
            "” — edit freely; filing sends it to the "
            "Approval queue as YOUR proposal:",
        QLineEdit::Normal, a.gloss, &ok);
    if (!ok || value.trimmed().isEmpty()) return;
    const QString evidence =
        "Promoted from the ALL Working Glossary AI draft (" +
        a.model + ", " + a.date + "; grounded in " + a.grounded +
        " — reference comparanda only, never Geshe Michael's "
        "English). Reviewed" +
        (value.trimmed() == a.gloss.trimmed() ? "" : " and edited") +
        " by the proposer before filing.";
    loadIdentity();
    fileProposal(parent, allcore::ProposalKind::WordRendering,
                 wylie, value.trimmed(), QString(), evidence);
}

// ---- ⌘D: the floating dictionary window (TibetDoc's dictionary
// window, reborn app-wide). Select Tibetan (or English) in ANY
// text surface and press ⌘D — the full Lookup stack answers in a
// floating card that follows its own q.v. links. One instance,
// created in main() once the layers exist. ------------------------
class LookupPopup : public QDialog {
public:
    LookupPopup(allcore::Spine& spine, allcore::RefDict* ref,
                allcore::Mvp* mvp, allcore::WhitneyRoots* whitney,
                allcore::ColloquialPron* colloq, QWidget* parent)
        : QDialog(parent), spine_(spine), ref_(ref), mvp_(mvp),
          whitney_(whitney), colloq_(colloq) {
        setWindowTitle("Lookup — ⌘D");
        setWindowFlag(Qt::Tool, true);   // floats above the app
        resize(540, 500);
        auto* v = new QVBoxLayout(this);
        box_ = new QLineEdit;
        box_->setPlaceholderText(
            "wylie · ACIP · English · pronunciation…");
        v->addWidget(box_);
        view_ = new QTextBrowser;
        view_->setOpenLinks(false);
        view_->setHtml(
            "<i style='color:#8A8A8A'>Select a word or phrase in "
            "any pane and press ⌘D — the whole dictionary stack "
            "answers here, without leaving your writing.</i>");
        v->addWidget(view_, 1);
        connect(box_, &QLineEdit::returnPressed,
                [this] { run(box_->text()); });
        connect(view_, &QTextBrowser::anchorClicked,
                [this](const QUrl& u) {
                    const QString s = u.toString();
                    if (s.startsWith("term:")) {
                        run(anchorPayload(s, 5));
                    } else if (s.startsWith("jae:")) {
                        showJaePage(this, s.mid(4).toInt());
                        run(box_->text());
                    } else if (s.startsWith("das:")) {
                        showDasPage(this, s.mid(4).toInt());
                        run(box_->text());
                    } else if (s.startsWith("propose:")) {
                        proposeTermDialog(
                            this, anchorPayload(s, 8),
                            "looked up in the ⌘D dictionary "
                            "window");
                        run(box_->text());
                    } else if (s.startsWith("proposeai:")) {
                        promoteAiDraftDialog(this,
                                             anchorPayload(s, 10));
                        run(box_->text());
                    } else if (s.startsWith("http")) {
                        QDesktopServices::openUrl(u);
                    }
                });
    }
    void run(const QString& q0) {
        QString q = q0;
        q.replace(QChar(0x2029), ' ');   // paragraph separators
        q = q.simplified();
        if (q.isEmpty()) {
            show();
            raise();
            box_->setFocus();
            return;
        }
        box_->setText(q);
        view_->setHtml(lookupResultsHtml(spine_, ref_, mvp_,
                                         whitney_, colloq_,
                                         q.toStdString()));
        show();
        raise();
    }
    QString viewText() const { return view_->toPlainText(); }

private:
    allcore::Spine& spine_;
    allcore::RefDict* ref_;
    allcore::Mvp* mvp_;
    allcore::WhitneyRoots* whitney_;
    allcore::ColloquialPron* colloq_;
    QLineEdit* box_ = nullptr;
    QTextBrowser* view_ = nullptr;
};
static LookupPopup* g_lookupPopup = nullptr;

// ---- Critical-edition collation core (shortlist #3): two
// witnesses of a text, diffed by the proven engine, rendered as a
// colored collation + a numbered apparatus of variant readings.
// Pure function so the selftest can drive it. ---------------------
static QString editionDiffHtml(const QString& a, const QString& b,
                               QString* apparatusMd = nullptr) {
    diff_match_patch dmp;
    auto diffs = dmp.diff_main(a, b);
    dmp.diff_cleanupSemantic(diffs);
    QString h, app;
    int lineA = 1, site = 0;
    QString pendDel;
    int pendLine = 1;
    auto flushSite = [&](const QString& ins) {
        const bool delReal = !pendDel.trimmed().isEmpty();
        const bool insReal = !ins.trimmed().isEmpty();
        if (!delReal && !insReal) {
            pendDel.clear();
            return;
        }
        ++site;
        QString kind = delReal && insReal
                           ? "substitution"
                           : (delReal ? "only in A" : "only in B");
        app += QString("%1. (A line ~%2, %3) A: “%4” | B: “%5”\n")
                   .arg(site)
                   .arg(pendLine)
                   .arg(kind)
                   .arg(delReal ? pendDel.trimmed().left(80)
                                : QString("—"))
                   .arg(insReal ? ins.trimmed().left(80)
                                : QString("—"));
        pendDel.clear();
    };
    for (const auto& d : diffs) {
        const QString t = d.text;
        if (d.operation == EQUAL) {
            flushSite(QString());
            h += t.toHtmlEscaped().replace("\n", "<br>");
            lineA += t.count('\n');
        } else if (d.operation == DELETE) {
            flushSite(QString());
            pendDel = t;
            pendLine = lineA;
            h += "<span style='background:#F5D5CE;color:#7A1F14;"
                 "text-decoration:line-through'>" +
                 t.toHtmlEscaped().replace("\n", "<br>") +
                 "</span>";
            lineA += t.count('\n');
        } else {   // INSERT (B-only)
            h += "<span style='background:#D5E8D2;color:#1E5B24'>" +
                 t.toHtmlEscaped().replace("\n", "<br>") +
                 "</span>";
            flushSite(t);
        }
    }
    flushSite(QString());
    const QString head =
        QString("<div style='margin-bottom:8px'><b>Edition "
                "collation</b> — %1 variant site(s). <span "
                "style='background:#F5D5CE'>&nbsp;A only&nbsp;"
                "</span> · <span style='background:#D5E8D2'>"
                "&nbsp;B only&nbsp;</span>; every reading shown, "
                "nothing resolved — the editor rules.</div>")
            .arg(site);
    if (apparatusMd)
        *apparatusMd =
            QString("# Apparatus — %1 variant site(s)\n\n")
                .arg(site) +
            app;
    return head + "<div style='line-height:1.7'>" + h + "</div>";
}

static std::function<void(QWidget*)> g_raisePane;
// sweep mode opens no native OS panels — the sweep reaper can
// reject QDialogs but not NSOpenPanel, so dialog-opening lanes
// short-circuit when this is set (main() sets it for --sweep)
static bool g_sweepActive = false;
// true under --selftest/--sweep/--screenshots: harness runs must
// neither restore nor OVERWRITE the translator's saved session
// (found 2026-08-15: the stray "QTextCursor::setPosition: Position
// '4' out of range" was restoreSession racing the selftest doc)
static bool g_harnessRun = false;

// ── Session memory ────────────────────────────────────────────────
// Adam, 2026-08-15: "make sure that the scan view in the input
// workflow and input pane remember which scan was last opened and
// what working folder was being worked with last... let's do that
// with all functions and tools and capabilities."
//
// One place every pane parks its "where I was" — open file, working
// folder, chosen scan, last query, chosen mode — and asks for it
// back at launch. The harness guard is the whole point of routing it
// through here: a --selftest or --sweep run neither reads nor writes
// any of it, so a probe can never move the translator's furniture.
namespace sess {

inline void put(const QString& key, const QVariant& v) {
    if (g_harnessRun) return;
    QSettings("ALL", "TranslationTool").setValue("sess/" + key, v);
}

inline QVariant get(const QString& key,
                    const QVariant& def = QVariant()) {
    if (g_harnessRun) return def;
    return QSettings("ALL", "TranslationTool")
        .value("sess/" + key, def);
}

inline QString str(const QString& key) {
    return get(key).toString();
}

// A remembered path is only worth restoring if it is still there —
// drives get unmounted, folders get renamed, scratch files get
// cleaned up. A vanished path restores as nothing, never as an
// error dialog on launch.
inline QString path(const QString& key) {
    const QString p = get(key).toString();
    return (!p.isEmpty() && QFileInfo::exists(p)) ? p : QString();
}

// Bind one control to session memory: seed it from last session at
// construction, write it back whenever the user changes it. Panes
// use these for the state that is a "where I was" rather than a
// preference — a search box, a filter, a mode.
static void remember(QLineEdit* w, const QString& key) {
    const QString v = sess::str(key);
    if (!v.isEmpty()) w->setText(v);
    QObject::connect(w, &QLineEdit::textChanged,
                     [key](const QString& t) { sess::put(key, t); });
}
static void remember(QComboBox* w, const QString& key) {
    const int i = sess::get(key, -1).toInt();
    if (i >= 0 && i < w->count()) w->setCurrentIndex(i);
    QObject::connect(w, &QComboBox::currentIndexChanged,
                     [key](int ix) { sess::put(key, ix); });
}
static void remember(QCheckBox* w, const QString& key) {
    const QVariant v = sess::get(key);
    if (v.isValid()) w->setChecked(v.toBool());
    QObject::connect(w, &QCheckBox::toggled,
                     [key](bool on) { sess::put(key, on); });
}
// Working text (a pasted passage, a draft in progress) is real work
// — losing it to a quit is worse than losing a scroll position. Held
// to a size cap so the settings file stays a settings file, and
// debounced so a long paste is not written on every keystroke.
static void remember(QPlainTextEdit* w, const QString& key,
                     int capKb = 256) {
    const QString v = sess::str(key);
    if (!v.isEmpty()) w->setPlainText(v);
    auto* t = new QTimer(w);
    t->setSingleShot(true);
    t->setInterval(1500);
    QObject::connect(t, &QTimer::timeout, w, [w, key, capKb] {
        const QString txt = w->toPlainText();
        if (txt.size() <= capKb * 1024) sess::put(key, txt);
    });
    QObject::connect(w, &QPlainTextEdit::textChanged, t,
                     [t] { t->start(); });
}

}   // namespace sess

