        v->addWidget(banner);
        doc_ = new QLabel;
        // #9A7A33 = the app's gold eyebrow tone — readable on the
        // dark and light chrome alike (night-mode audit 2026-08-12)
        doc_->setStyleSheet("color:#9A7A33;font-size:13px");
        v->addWidget(doc_);
        auto mk = [&](const QString& title, const QString& what) {
            auto* b = new QPushButton(title);
            b->setMinimumHeight(34);
            v->addWidget(b);
            auto* d = new QLabel(what);
            d->setWordWrap(true);
            d->setStyleSheet("color:#8A8A8A;font-size:12px;"
                             "margin-bottom:6px");
            v->addWidget(d);
            return b;
        };
        auto* prepB = mk(
            "Prepare for translation (Mixed Nuts)…",
            "The demonstrated GMR workflow: paragraphs at double "
            "shads, bracket notes folio-tagged, saved as a prep "
            "text for the translation bench.");
        auto* pechaB = mk(
            "Make pecha (PDF)…",
            "An authentic long-format pecha: framed folio sides, "
            "rotated Tibetan folio numerals, your typeface, "
            "optional phonetics interlinear — preview before "
            "saving.");
        auto* batchB = mk(
            "Batch: folder of texts → pecha set…",
            "Every text file (*.txt, *.act, *.acip — ACIP or "
            "wylie) in a chosen folder becomes its own pecha PDF "
            "in an output folder, using the saved Make-pecha "
            "options (page, rules, layout, interlinears). "
            "Per-text dress (title folio, margin title) stays "
            "off in batch. Needs no loaded document.");
        auto* printB = mk(
            "Export print Tibetan (Unicode)…",
            "Clean print-ready Tibetan Unicode with the classical "
            "shad rules; anything the engine cannot convert is "
            "flagged ⟨wylie⟩, never guessed.");
        results_ = new QTextBrowser;
        results_->setHtml(
            "<i style='color:#8A8A8A'>Results appear here. Load a "
            "text in Read → Overlay, then choose an action above — "
            "or run the batch lane on a whole folder without "
            "loading anything.</i>");
        v->addWidget(results_, 1);
        connect(prepB, &QPushButton::clicked, [this] {
            if (!guard()) return;
            results_->setHtml(overlay_->prepareForTranslation());
        });
        connect(pechaB, &QPushButton::clicked, [this] {
            if (!guard()) return;
            results_->setHtml(overlay_->pechaExport());
        });
        connect(batchB, &QPushButton::clicked, [this] {
            // deliberately no guard() — batch reads a folder, not
            // the loaded document
            const QString h = overlay_ ? overlay_->pechaBatch()
                                       : QString();
            if (!h.isEmpty()) results_->setHtml(h);
        });
        connect(printB, &QPushButton::clicked, [this] {
            if (!guard()) return;
            results_->setHtml(overlay_->exportPrintTibetan());
        });
